package GUI;
import GUI.components.*; import Program.model.*; import Program.service.*; import Program.utils.DateUtils; import javafx.geometry.*; import javafx.scene.chart.*; import javafx.scene.control.*; import javafx.scene.layout.*; import java.time.*; import java.util.*;
public class DashboardUI extends ScrollPane {public DashboardUI(User user,TransactionService transactions,BudgetService budgets,MainUI app){setFitToWidth(true);String id=user.getId();LocalDate monthStart=DateUtils.firstDayOfMonth();List<Transaction>items=transactions.all(id);Map<String,Double>spending=transactions.expenseByCategory(id,monthStart,LocalDate.now());AIService ai=new AIService();List<String>alerts=ai.localAlerts(id);VBox page=UIFactory.page(greeting(user.getFullName()),subtitle(alerts));double income=items.stream().filter(t->t instanceof Income&&!t.getDate().isBefore(monthStart)).mapToDouble(Transaction::getAmount).sum(),expenses=items.stream().filter(t->t instanceof Expense&&!t.getDate().isBefore(monthStart)).mapToDouble(Transaction::getAmount).sum();HBox cards=new HBox(14,new StatCard("TOTAL INCOME",money(income),"#22C55E"),new StatCard("TOTAL EXPENSES",money(expenses),"#EF4444"),new StatCard("BALANCE",money(income-expenses),"#38BDF8"),new StatCard("SAVINGS RATE",income==0?"—":String.format("%.1f%%",(income-expenses)*100/income),"#A78BFA"));cards.getChildren().forEach(n->HBox.setHgrow(n,Priority.ALWAYS));LineChart<String,Number>line=new LineChart<>(new CategoryAxis(),new NumberAxis());line.setLegendVisible(false);line.setTitle("Spending Trend");XYChart.Series<String,Number>series=new XYChart.Series<>();for(int day=6;day>=0;day--){LocalDate date=LocalDate.now().minusDays(day);double total=items.stream().filter(t->t instanceof Expense&&t.getDate().equals(date)).mapToDouble(Transaction::getAmount).sum();series.getData().add(new XYChart.Data<>(String.valueOf(date.getDayOfMonth()),total));}line.getData().add(series);PieChart pie=new PieChart();pie.setTitle("Expense Breakdown");transactions.expenseByCategory(id,monthStart,LocalDate.now()).forEach((category,value)->pie.getData().add(new PieChart.Data(category+" · "+money(value),value)));VBox left=card("Spending Trend",line),right=card("Expense Breakdown",pie);HBox charts=new HBox(14,left,right);charts.getChildren().forEach(n->{HBox.setHgrow(n,Priority.ALWAYS);((VBox)n).setPrefWidth(500);});VBox alertBox=new VBox(8);alertBox.getStyleClass().add("glass-card");alertBox.setPadding(new Insets(16));alertBox.getChildren().add(new Label("🔔  AI FINANCIAL ALERTS"));alerts.forEach(alert->alertBox.getChildren().add(new AlertCard(alert)));VBox budgetBox=new VBox(8);budgetBox.getStyleClass().add("glass-card");budgetBox.setPadding(new Insets(16));budgetBox.getChildren().add(new Label("🎯  BUDGET OVERVIEW"));for(Budget budget:budgets.load(id))budgetBox.getChildren().add(new BudgetCard(budget.getCategory(),spending.getOrDefault(budget.getCategory(),0d),budget.getLimit()));HBox lower=new HBox(14,alertBox,budgetBox);lower.getChildren().forEach(n->HBox.setHgrow(n,Priority.ALWAYS));TransactionTable table=new TransactionTable();table.setPrefHeight(230);table.setTransactions(items.stream().limit(10).toList());page.getChildren().addAll(cards,charts,lower,card("📜  RECENT TRANSACTIONS",table));setContent(page);}
 private String greeting(String name){int hour=LocalTime.now().getHour();String salutation=hour>=5&&hour<12?"Good morning":hour<17?"Good afternoon":hour<21?"Good evening":"Good night";return salutation+", "+name+" 👋";}private String subtitle(List<String>alerts){if(alerts.stream().anyMatch(alert->alert.contains("🔴")))return "One of your budgets needs attention today.";if(alerts.stream().anyMatch(alert->alert.contains("🟠")))return "You are approaching a budget limit — review your spending.";int hour=LocalTime.now().getHour();return hour>=21||hour<5?"A quiet moment to plan tomorrow’s finances.":hour<12?"Start the day with a clear view of your finances.":hour<17?"Here’s your live financial overview for today.":"Review today’s spending and keep your goals on track.";}private VBox card(String title,javafx.scene.Node content){VBox box=new VBox(8,new Label(title),content);box.setPadding(new Insets(14));box.getStyleClass().add("glass-card");VBox.setVgrow(content,Priority.ALWAYS);return box;}private String money(double amount){return String.format("৳%,.0f",amount);}}
